contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need to call airDrop as msg.sender = this contract. Bank.supportsToken() expects msg.sender to be a Bank,
    // so we will call airDrop via a Bank-like contract by using the existing Bank contract at address(this).
    // However, in the given setup msg.sender for c.calls will be this test contract, so supportsToken() is called on Bank(msg.sender)
    // which will be Bank(address(this)). To satisfy supportsToken(), this contract must implement supportsToken().
    // Implement it via receive fallback to return the correct bytes32 through a callable function by creating a thin shim:

    // Single public test function per constraints
    function run() public payable {
        // ensure this contract has no existing token balance initially (fresh c deployed by checker)
        // read before balance
        uint before = c.tokenBalance(address(this));

        bool reverted;
        // call airDrop and catch revert
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = c.tokenBalance(address(this));
        // also read the _locked flag via its public getter name _locked
        bool locked = c._locked();

        // Rule: If call did not revert then before must have been 0 and after == before + 20; if it reverted then after == before.
        // Also, regardless, the lock must be false at end.
        assert((!reverted && before == 0 && after == before + 20 || reverted && after == before) && locked == false);
    }

    // Provide supportsToken() so that when c.airDrop() calls Bank(msg.sender).supportsToken() it succeeds.
    // The Bank in original code declares supportsToken() external pure returns (bytes32)
    // Here we implement a matching external function.
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    receive() external payable {}
}

