        // selector for supportsToken(): 0x4e4e9fdb
        if (sel == 0x4e4e9fdb) {
            bytes32 v = keccak256(abi.encodePacked("Nu Token"));
            assembly {
                mstore(0x0, v)
                return(0x0, 0x20)
            }
        }
        // otherwise do nothing
    }

    receive() external payable {}
}

