contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a boolean param chooseZero to decide whether we start from zero balance or not.
    // If chooseZero==true we ensure msg.sender (this test contract) has zero balance in c before calling airDrop.
    // If chooseZero==false we first call airDrop once (via a Bank-supporting call) to give a nonzero balance,
    // then calling airDrop again must revert due to hasNoBalance modifier.
    function run(bool chooseZero) public payable {
        require(true);

        // observe initial balance
        uint before = c.tokenBalance(address(this));

        // We need to simulate Bank(msg.sender).supportsToken() comparison used in supportsToken modifier.
        // In C.supportsToken modifier, it calls Bank(msg.sender).supportsToken(), thus the msg.sender of C.airDrop must be a contract
        // implementing supportsToken() returning keccak256("Nu Token") as bytes32. Our InvMutTest contract is not Bank, so
        // we must call airDrop through an intermediate contract that implements supportsToken. However the problem statement
        // prohibits redeclaring other contracts. But Bank already exists in the compilation unit and matches the expected interface.
        // To have msg.sender be Bank, this InvMutTest can call c.airDrop() directly only if msg.sender (this contract) equals Bank — impossible.
        // Instead we can exploit that C.supportsToken calls Bank(msg.sender).supportsToken(); msg.sender must be a contract whose supportsToken() returns
        // the expected bytes32. We cannot deploy a new contract, but we can reuse the existing Bank contract by making calls originate from that Bank instance.
        // To do that, we perform a low-level call: call Bank(address).call{value:0}(encoded function selector that will in turn call c.airDrop())
        // However the constraints forbid deploying or redeclaring contracts; we can still use the existing Bank contract at address of a freshly deployed Bank that is part of the compilation unit.
        // The checker deploys a fresh C and passes it to us; Bank already exists in the compilation unit but not deployed. We cannot instantiate new Bank here.
        // Therefore, to satisfy the modifiers, we will instead call c.airDrop() directly and catch revert — when msg.sender is not a supporting contract, supportsToken() will call Bank(msg.sender).supportsToken()
        // on an address that does not implement supportsToken resulting in a revert; that revert will prevent state changes. We will capture that behavior.

        // First branch: enforce starting from zero and then attempt airDrop and check resulting balance is 20 if call succeeded.
        if (chooseZero) {
            // If before != 0 then we cannot satisfy hasNoBalance precondition of airDrop; require that the general rule only applies when before==0
            // We invoke airDrop and catch whether it reverts.
            bool reverted;
            try c.airDrop() {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint after = c.tokenBalance(address(this));
            // General rule: if before==0 and call did not revert then after == before + 20 (i.e., 20), and if call reverted then after == before (no change)
            assert((before == 0 && !reverted && after == before + 20) || (before == 0 && reverted && after == before) || (before != 0 && after == before));
            return;
        }

        // Second branch: make sure when starting with nonzero balance, calling airDrop reverts and balance doesn't change.
        // If we already have nonzero before, then airDrop should revert because of hasNoBalance. We'll check that.
        if (before == 0) {
            // try to first get nonzero by calling airDrop once: if that succeeds, we now have nonzero and can test second call; otherwise we cannot force nonzero so we skip assertion requiring nonzero.
            bool firstReverted;
            try c.airDrop() {
                firstReverted = false;
            } catch {
                firstReverted = true;
            }
            // read updated balance
            uint mid = c.tokenBalance(address(this));
            if (!firstReverted && mid > 0) {
                // now calling again must revert due to hasNoBalance
                bool secondReverted;
                try c.airDrop() {
                    secondReverted = false;
                } catch {
                    secondReverted = true;
                }
                uint after = c.tokenBalance(address(this));
                // general rule: when caller already has nonzero balance, calling airDrop reverts and balance unchanged
                assert(mid != 0 && secondReverted && after == mid);
                return;
            } else {
                // Could not make nonzero (first call reverted), so we cannot perform the second-call test. In that case assert that nothing changed.
                uint after = c.tokenBalance(address(this));
                assert(after == before);
                return;
            }
        } else {
            // before != 0: calling airDrop now should revert and leave balance unchanged
            bool reverted2;
            try c.airDrop() {
                reverted2 = false;
            } catch {
                reverted2 = true;
            }
            uint after2 = c.tokenBalance(address(this));
            assert(reverted2 && after2 == before);
            return;
        }
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // chooseZero: if true we try the path starting from zero balance; if false we try the path starting from nonzero balance.
    function run(bool chooseZero) public payable {
        require(true);

        // observe initial balance
        uint before = c.tokenBalance(address(this));

        // Helper to attempt airDrop and record revert flag
        bool reverted1;
        try c.airDrop() {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }
        uint after1 = c.tokenBalance(address(this));

        if (chooseZero) {
            // If we started from zero then two possibilities:
            // - call succeeded: balance increased by 20
            // - call reverted: balance unchanged
            assert((before == 0 && !reverted1 && after1 == before + 20) || (before == 0 && reverted1 && after1 == before) || (before != 0 && after1 == before));
            return;
        }

        // chooseZero == false: aim to ensure that when caller already has nonzero balance, airDrop reverts and balance unchanged.
        if (before != 0) {
            // we started with nonzero: the single attempted call should have reverted and left balance unchanged
            assert(reverted1 && after1 == before);
            return;
        }

        // before == 0 and chooseZero == false: try to reach a nonzero state by calling again if first attempt succeeded
        if (!reverted1 && after1 == before + 20) {
            // now we have nonzero balance; calling again must revert and not change balance
            bool reverted2;
            try c.airDrop() {
                reverted2 = false;
            } catch {
                reverted2 = true;
            }
            uint after2 = c.tokenBalance(address(this));
            assert(reverted2 && after2 == after1);
            return;
        }

        // first attempt either reverted or did not produce expected +20; in that case nothing should have changed
        uint finalBal = c.tokenBalance(address(this));
        assert(finalBal == before);
    }

    receive() external payable { }
}

