contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // msg.sender for calls to c will be this contract.
    // We provide an arbitrary address parameter to act as the external caller via a helper Bank contract already in the compilation unit.
    // Since c.supportsToken checks Bank(msg.sender).supportsToken(), we must call airDrop from an address whose supportsToken returns the correct bytes32.

    function run(address caller) public payable {
        require(caller != address(0));
        // Ensure the test contract currently has balance >= 0 (no Ether use needed).

        // Precondition: tokenBalance for this contract (msg.sender to c) must be 0 to satisfy hasNoBalance.
        // The freshly deployed c in the checker might have nonzero balance for this test contract; ensure it's zero by reading it.
        uint before = c.tokenBalance(address(this));

        // If before is nonzero, then airDrop would revert due to hasNoBalance; in that case we assert that it indeed reverts.
        bool reverted = false;
        if (before != 0) {
            try c.airDrop() {
                reverted = false;
            } catch {
                reverted = true;
            }
            // Rule: if caller (this contract) already has non-zero balance, the call must revert and balance unchanged.
            uint after = c.tokenBalance(address(this));
            assert(reverted && after == before);
            return;
        }

        // At this point, before == 0. We need to simulate calling from an external Bank that reports supportsToken == keccak256("Nu Token").
        // The provided Bank contract's supportsToken returns that exact hash when called on its own address. So we require caller to be a contract of type Bank.
        // We cannot instantiate new Bank here; but the checker will choose caller. We only require that calling c.airDrop from this contract's context will be attempted —
        // however c.supportsToken uses Bank(msg.sender).supportsToken(), where msg.sender is this InvMutTest contract. Thus to satisfy the modifier, the InvMutTest contract must be such that Bank(address(this)).supportsToken() equals keccak256("Nu Token").
        // The existing Bank contract's supportsToken is a free function on that type; but casting address(this) to Bank and calling supportsToken() will call the external function on THIS contract address — which will fail unless THIS contract implements that function. To work within constraints, we instead call c.airDrop via a delegate: we call c.airDrop() directly because msg.sender for c will be this contract. So for the supportsToken modifier to succeed, Bank(msg.sender).supportsToken() must equal the hash. That requires that address(this) when viewed as Bank responds accordingly. We cannot change this, so the test captures both possibilities: either the call reverts due to supportsToken mismatch, or it succeeds and increases balance by 20.

        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = c.tokenBalance(address(this));

        // General rule:
        // - If call reverted then balance must remain zero.
        // - If call succeeded then balance must be exactly 20 and the lock (_locked) must be false (no permanent reentrancy lock). We observe lock indirectly by attempting another airDrop: if _locked were stuck true, the second call would always revert even if preconditions failed; so we attempt a second call and ensure behavior consistent with unlocked state.
        if (reverted) {
            assert(after == before);
        } else {
            // succeeded: balance increased by 20
            // after should be exactly before + 20 (before was 0)
            assert(after == before + 20);

            // Now ensure _locked was reset: since hasNoBalance requires tokenBalance[msg.sender]==0, the second airDrop should revert due to hasNoBalance (because after != 0). But it must not revert due to a stuck _locked, i.e., it may revert but for the expected reason. We call and catch the revert, then assert balance unchanged.
            bool secondReverted = false;
            try c.airDrop() {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
            uint after2 = c.tokenBalance(address(this));
            // The second call must revert (hasNoBalance) and must not have changed the balance, and the balance remains 20.
            assert(secondReverted && after2 == after);
        }
    }

    // Provide an implementation of supportsToken so that if the checker deploys InvMutTest as the caller, Bank(address(this)).supportsToken() returns the correct value.
    // This lets the airDrop call succeed when invoked from this contract.
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    receive() external payable {}
}

